// petdex hook plugin. Auto-generated by 'petdex hooks install'.
// Forwards OpenCode lifecycle events to the petdex desktop mascot via HTTP.
// Edit STATE_MAP below to customize which state each event triggers.

import { createHash } from "node:crypto";
import { appendFileSync, existsSync, mkdirSync, readFileSync, renameSync, statSync, unlinkSync } from "node:fs";
import { readFile } from "node:fs/promises";
import { homedir } from "node:os";
import { join } from "node:path";

const HOOK_SERVER_URL = "http://127.0.0.1:7777/state";
const HOOK_SERVER_BUBBLE_URL = "http://127.0.0.1:7777/bubble";
const HOOK_SERVER_TITLE_URL = "http://127.0.0.1:7777/bubble/title";
const RUNTIME_DIR = join(homedir(), ".petdex", "runtime");
const TOKEN_PATH = join(RUNTIME_DIR, "update-token");
const KILLSWITCH_PATH = join(RUNTIME_DIR, "hooks-disabled");
const REMOTE_HOST_PATH = join(RUNTIME_DIR, "remote-host");
const JOURNAL_DIR = join(RUNTIME_DIR, "session-journal");
const JOURNAL_LIMIT = 4 * 1024 * 1024;

export function journalStem(value, fallback) {
  return createHash("sha256").update(String(value || fallback), "utf8").digest("hex");
}

function appendJournal(body) {
  if (!body?.text || !body?.conversation_key) return;
  try {
    mkdirSync(JOURNAL_DIR, { recursive: true, mode: 0o700 });
    const path = join(JOURNAL_DIR, `${journalStem(body.agent_source, "agent")}-${journalStem(body.conversation_key, "unkeyed")}.jsonl`);
    const record = JSON.stringify({ journal_version: 1, event: body }) + "\n";
    if (existsSync(path) && statSync(path).size + Buffer.byteLength(record) > JOURNAL_LIMIT) {
      const previous = path + ".1";
      try { unlinkSync(previous); } catch {}
      renameSync(path, previous);
    }
    appendFileSync(path, record, { encoding: "utf8", mode: 0o600 });
  } catch {
    // Recovery is best-effort and must never stain the agent process.
  }
}

async function readToken() {
  try {
    return (await readFile(TOKEN_PATH, "utf8")).trim();
  } catch {
    return null;
  }
}

function fieldFrom(input, key) {
  if (input == null || typeof input !== "object") return null;
  const value = input[key];
  return typeof value === "string" ? value : null;
}

function basename(filePath) {
  const slash = Math.max(filePath.lastIndexOf("/"), filePath.lastIndexOf("\\"));
  return slash >= 0 ? filePath.slice(slash + 1) : filePath;
}

function clip(text, max = 40) {
  return text.length <= max ? text : text.slice(0, max - 1) + "…";
}

// V2 runs plugins inside the shared background service, so its cwd and
// TERM_PROGRAM belong to the service, not the session: V2 passes the plugin
// location instead and claims no terminal.
function originMetadata(cwd) {
  const sourceApp = cwd ? undefined : process.env.TERM_PROGRAM;
  const sourceCwd = cwd ?? process.cwd();
  const metadata =
    sourceApp === "Apple_Terminal" || sourceApp === "vscode"
      ? { source_app: sourceApp, source_cwd: sourceCwd }
      : { source_cwd: sourceCwd };
  try {
    const hostname = readFileSync(REMOTE_HOST_PATH, "utf8").trim().slice(0, 64);
    if (hostname) return { ...metadata, hostname, remote: true };
  } catch {}
  return metadata;
}

function canonicalToolKind(toolName) {
  const lower = String(toolName || "").toLowerCase();
  if (lower === "read") return "read";
  if (lower === "edit" || lower === "multiedit") return "edit";
  if (lower === "write") return "write";
  if (lower === "bash" || lower === "shell") return "bash";
  if (lower === "grep") return "grep";
  if (lower === "glob") return "glob";
  if (lower === "webfetch" || lower === "websearch") return "webfetch";
  if (lower === "task" || lower === "agent") return "task";
  return "unknown";
}

function formatTool(toolName, toolInput, phase) {
  const past = phase === "done";
  switch (canonicalToolKind(toolName)) {
    case "read": {
      const path = fieldFrom(toolInput, "file_path") ?? fieldFrom(toolInput, "filePath") ?? fieldFrom(toolInput, "path");
      const name = path ? clip(basename(path)) : null;
      return name ? (past ? "Read " + name : "Reading " + name) : past ? "Read file" : "Reading file";
    }
    case "edit":
    case "write": {
      const path = fieldFrom(toolInput, "file_path") ?? fieldFrom(toolInput, "filePath") ?? fieldFrom(toolInput, "path");
      const name = path ? clip(basename(path)) : null;
      return name ? (past ? "Edited " + name : "Editing " + name) : past ? "Edited file" : "Editing file";
    }
    case "bash": {
      const command = fieldFrom(toolInput, "command");
      if (command) {
        const head = clip(command.split(/\s+/)[0] || command, 24);
        return past ? "Ran " + head : "Running " + head;
      }
      return past ? "Ran command" : "Running command";
    }
    case "grep": {
      const pattern = fieldFrom(toolInput, "pattern");
      // Curly quotes: JSON.stringify escapes an ASCII `"` correctly, but
      // the hook server reads the body back with a scanner that stops at the
      // backslash, so the pattern never reaches the bubble.
      return pattern ? (past ? "Searched “" + clip(pattern, 28) + "”" : "Searching “" + clip(pattern, 28) + "”") : past ? "Searched files" : "Searching files";
    }
    case "glob": {
      const pattern = fieldFrom(toolInput, "pattern");
      return pattern ? (past ? "Listed " + clip(pattern, 28) : "Listing " + clip(pattern, 28)) : past ? "Listed files" : "Listing files";
    }
    case "webfetch": {
      const url = fieldFrom(toolInput, "url");
      if (url) {
        try {
          const host = new URL(url).hostname;
          return past ? "Fetched " + clip(host, 28) : "Fetching " + clip(host, 28);
        } catch {}
      }
      return past ? "Fetched web" : "Searching web";
    }
    case "task":
      return past ? "Subagent done" : "Spawning subagent";
    default: {
      const name = clip(String(toolName || "tool"), 28);
      return past ? "Called " + name : "Calling " + name;
    }
  }
}

async function postJson(url, body, token) {
  try {
    await fetch(url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Petdex-Update-Token": token,
      },
      body: JSON.stringify(body),
      // 300ms instead of 1s: well above any real localhost roundtrip
      // and below the threshold an agent user notices as latency.
      signal: AbortSignal.timeout(300),
    });
  } catch {
    // Hook server offline: stay quiet, the agent should not notice.
  }
}

async function notify({ state, duration, text, title, busy, sessionId, status, messageKind = "tool", cwd }) {
  // Killswitch: users toggle this with /petdex inside their agent
  // (or 'petdex hooks toggle' from a shell). Bail before the token
  // read so the disabled state has zero filesystem cost beyond the
  // existsSync.
  if (existsSync(KILLSWITCH_PATH)) return;
  // Stamp agent_source so the hook server can route per-pet when we
  // ship multi-mascot. Today the field is recorded for telemetry
  // but doesn't affect routing.
  const stateBody =
    duration != null
      ? { state, duration, agent_source: "opencode" }
      : { state, agent_source: "opencode" };
  const metadata = originMetadata(cwd);
  Object.assign(stateBody, metadata);
  const bubbleBody = { text, agent_source: "opencode", ...metadata };
  if (sessionId) {
    stateBody.session_id = sessionId;
    bubbleBody.session_id = sessionId;
    bubbleBody.conversation_key = sessionId;
    bubbleBody.source_session_id = sessionId;
    bubbleBody.session_kind = "primary";
  }
  if (title) {
    bubbleBody.title = title;
    bubbleBody.title_source = "server";
  }
  if (busy !== undefined) bubbleBody.busy = busy;
  if (status) bubbleBody.status = status;
  bubbleBody.message_kind = messageKind;
  bubbleBody.feed_source = "hook";
  appendJournal(bubbleBody);
  // Journal first: an event remains recoverable when the desktop is closed.
  // The rotating token still gates all loopback HTTP writes.
  const token = await readToken();
  if (!token) return;
  await Promise.all([
    postJson(HOOK_SERVER_URL, stateBody, token),
    text ? postJson(HOOK_SERVER_BUBBLE_URL, bubbleBody, token) : Promise.resolve(),
  ]);
}

function createPetdex({ fetchTitle, cwd }) {
  const titleCache = new Map();
  const clippedTitle = (title) =>
    typeof title === "string" && title.trim().length > 0
      ? (title.trim().length > 60 ? title.trim().slice(0, 59) + "\u2026" : title.trim())
      : null;
  async function sessionTitle(sessionID) {
    if (!sessionID) return null;
    try {
      const title = clippedTitle(await fetchTitle(sessionID));
      if (title) titleCache.set(sessionID, title);
    } catch {
      // Hook-server silence: a missing title never stains the agent.
    }
    return titleCache.get(sessionID) || null;
  }
  async function syncServerTitle(sessionID, rawTitle) {
    const title = clippedTitle(rawTitle);
    if (!sessionID || !title) return;
    titleCache.set(sessionID, title);
    if (existsSync(KILLSWITCH_PATH)) return;
    const token = await readToken();
    if (!token) return;
    await postJson(HOOK_SERVER_TITLE_URL, {
      session_id: sessionID,
      conversation_key: sessionID,
      title,
      agent_source: "opencode",
      ...originMetadata(cwd),
    }, token);
  }
  const tool = async (phase, toolName, args, sessionId) => notify({
    state: phase === "done" ? "idle" : "running",
    text: formatTool(toolName, args, phase),
    title: await sessionTitle(sessionId),
    busy: true,
    sessionId,
    status: "running",
    messageKind: "tool",
    cwd,
  });
  const idle = async (sessionId) => notify({
    state: "waving",
    duration: 1500,
    text: "Done.",
    title: await sessionTitle(sessionId),
    busy: false,
    sessionId,
    status: "completed",
    messageKind: "lifecycle",
    cwd,
  });
  const failed = async (sessionId) => notify({
    state: "failed",
    duration: 2500,
    text: "OpenCode hit an error.",
    title: await sessionTitle(sessionId),
    busy: false,
    sessionId,
    status: "failed",
    messageKind: "lifecycle",
    cwd,
  });
  return { syncServerTitle, tool, idle, failed };
}

const PetdexPlugin = async ({ client }) => {
  const petdex = createPetdex({
    fetchTitle: async (id) => (client ? (await client.session.get({ path: { id } }))?.data?.title : null),
  });
  return {
    "tool.execute.before": async (input, output) => petdex.tool("running", input.tool, output.args, input.sessionID),
    "tool.execute.after": async (input) => petdex.tool("done", input.tool, input.args, input.sessionID),
    event: async ({ event }) => {
      const info = event?.properties?.info;
      const sessionId = event?.properties?.sessionID ?? info?.id;
      if (typeof sessionId !== "string" || sessionId.length === 0) return;
      if (event.type === "session.updated" || event.type === "session.created") {
        await petdex.syncServerTitle(sessionId, info?.title);
      } else if (event.type === "session.idle") {
        await petdex.idle(sessionId);
      } else if (event.type === "session.error") {
        await petdex.failed(sessionId);
      }
    },
  };
};

// V2 plugin API: hooks register on the context, and events arrive as one
// server-wide stream with the payload under `data`.
async function setup(ctx) {
  const directory = ctx.location?.directory;
  const petdex = createPetdex({
    fetchTitle: async (sessionID) => (await ctx.session.get({ sessionID }))?.title,
    cwd: directory,
  });
  await ctx.tool.hook("execute.before", (event) => petdex.tool("running", event.tool, event.input, event.sessionID));
  await ctx.tool.hook("execute.after", (event) => petdex.tool("done", event.tool, event.input, event.sessionID));
  const controller = new AbortController();
  void (async () => {
    for await (const event of ctx.event.subscribe({ signal: controller.signal })) {
      // One plugin instance loads per location; skip other locations'
      // sessions so each event reaches the mascot once.
      if (event?.location?.directory && directory && event.location.directory !== directory) continue;
      const sessionId = event?.data?.sessionID;
      if (typeof sessionId !== "string" || sessionId.length === 0) continue;
      if (event.type === "session.created" || event.type === "session.renamed") {
        await petdex.syncServerTitle(sessionId, event.data.title);
      } else if (event.type === "session.idle") {
        await petdex.idle(sessionId);
      } else if (event.type === "session.execution.failed") {
        await petdex.failed(sessionId);
      }
    }
  })().catch(() => {
    // Stream closed or aborted: the agent should not notice.
  });
  return () => controller.abort();
}

export default { id: "petdex", setup, server: PetdexPlugin };
export { PetdexPlugin };
